import React, { useState } from 'react';
import './RecipeGenerator.css';

const RecipeGenerator = ({ onRecipeGenerated }) => {
  const [ingredients, setIngredients] = useState('');
  const [servings, setServings] = useState(2);
  const [isLoading, setIsLoading] = useState(false);

  const backendURL = "http://127.0.0.1:8000"; // FastAPI base URL

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!ingredients.trim()) return;
    setIsLoading(true);

    try {
      // Step 1: Fetch suggested recipes based on ingredients
      const suggestResponse = await fetch(
        backendURL + '/ingredients/suggest_recipes', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ ingredients, top_n: 5 })
        }
      );

      if (!suggestResponse.ok) throw new Error("Failed to fetch recipe suggestions");

      const suggestions = await suggestResponse.json();

      // Step 2: Fetch full details for each suggested recipe
      const fullRecipes = await Promise.all(
        suggestions.map(async (r) => {
          const fullResponse = await fetch(
            backendURL + '/ingredients/recipe_full/' + r.index, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ num_people: servings })
            }
          );
          const fullData = await fullResponse.json();
          return {
            id: r.index,
            name: fullData.dish_name,
            cuisine: fullData.cuisine,
            type: fullData.type,
            cookTime: fullData.time_to_prepare_minutes + ' mins',
            ingredients: fullData.ingredients.map((i) => ({ name: i })),
            instructions: fullData.instructions.split('\n'),
            matched: r.matched,
            missing: r.missing
          };
        })
      );

      const recipeData = {
        type: 'recipe-generation',
        query: ingredients,
        servings: servings,
        recipes: fullRecipes,
        totalFound: fullRecipes.length
      };

      setIsLoading(false);
      onRecipeGenerated(recipeData);
    } catch (err) {
      console.error("Error:", err);
      setIsLoading(false);
      alert("Error fetching recipes. Please make sure FastAPI is running.");
    }
  };

  return (
    <section className="recipe-generator">
      <div className="container">
        <h1 className="page-title">🍳 Recipe Generator</h1>
        <p className="page-subtitle">
          Enter your ingredients and we'll suggest matching recipes!
        </p>

        <form onSubmit={handleSubmit} className="generator-form card">
          <label className="form-label">
            Available Ingredients
          </label>
          <textarea
            className="form-input form-textarea"
            placeholder="e.g., rice, onion, tomato, garlic"
            value={ingredients}
            onChange={(e) => setIngredients(e.target.value)}
            required
          />

          <label className="form-label">
            Number of Servings
          </label>
          <input
            type="number"
            className="form-input"
            min="1"
            max="20"
            value={servings}
            onChange={(e) => setServings(parseInt(e.target.value))}
          />

          <button
            type="submit"
            className="btn btn-primary btn-large w-full"
            disabled={isLoading}
          >
            {isLoading ? "Generating..." : "Generate Recipes ✨"}
          </button>
        </form>

        <div className="tips-section card">
          <h3>💡 Tips</h3>
          <ul>
            <li>Separate ingredients by commas</li>
            <li>Be specific with ingredient names</li>
            <li>Make sure your FastAPI backend is running on port 8000</li>
          </ul>
        </div>
      </div>
    </section>
  );
};

export default RecipeGenerator;
